const incoming=(()=>{try{return $('When executed by another workflow').first().json||{}}catch{return $json||{}}})();
const root=incoming&&typeof incoming==='object'?incoming:{};
const body=root.body&&typeof root.body==='object'?root.body:root;
const packet=body.specialist_packet&&typeof body.specialist_packet==='object'?body.specialist_packet:null;
let task=body.agent_task&&typeof body.agent_task==='object'?body.agent_task:(body.case_id||body.task_id||body.objective?body:null);
if(!task||typeof task!=='object') task={};
if(packet){
  const inputs=packet.inputs&&typeof packet.inputs==='object'?packet.inputs:{};
  task={
    case_id:String(packet.case_id||body.case_id||task.case_id||''),
    task_id:String(packet.task_id||task.task_id||''),
    agent_id:'excel_extractor',
    objective:String(packet.objective||task.objective||''),
    handoff_message:String(packet.handoff_message||task.handoff_message||packet.objective||''),
    inputs,
    context:packet.context&&typeof packet.context==='object'?packet.context:(task.context||{}),
    constraints:packet.controls&&typeof packet.controls==='object'?packet.controls:(task.constraints||{})
  };
}
task.agent_id='excel_extractor';
task.case_id=String(task.case_id||'');
task.task_id=String(task.task_id||'');
task.objective=String(task.objective||'');
task.handoff_message=String(task.handoff_message||'');
task.inputs=task.inputs&&typeof task.inputs==='object'?task.inputs:{};
task.context=task.context&&typeof task.context==='object'?task.context:{};
const cfg=$('Runtime configuration').first().json||{};
if(!task.inputs.activity_base_url&&cfg.activity_base_url) task.inputs={...task.inputs, activity_base_url:cfg.activity_base_url};
return [{json:{...cfg, agent_task:task, case_id:task.case_id, task_id:task.task_id}}];

const opened=$json||{};
const result=opened.result&&typeof opened.result==='object'?opened.result:{};
return [{json:{
  task_id:result.task_id||opened.task_id||'',
  agent_id:'excel_extractor',
  status:result.status||'needs_input',
  message:result.message||opened.message||'Нет Excel-файла для извлечения',
  data:result.data||{},
  artifacts:result.artifacts||{},
  issues:result.issues||[{type:'missing_excel'}],
  assumptions:result.assumptions||[],
  requests:result.requests||[{question_id:'Q-excel',question:'Приложите workbook .xlsx',options:[]}]
}}];

const x=$('Restore after Excel Extractor accepted').first().json||{};
const cap=String(x.suggested_capability||'').trim();
const known=cap==='commissioning'?cap:'operations';
return [{json:{...x, suggested_capability:known}}];

const raw=$json||{};
const data=raw.data&&typeof raw.data==='object'?raw.data:{};
const facts=Array.isArray(data.facts)?data.facts:[];
const n=Number(data.total_count!=null?data.total_count:facts.length);
const httpError=raw.error&&typeof raw.error==='object'?raw.error:null;
const status=String(raw.status||(httpError?'failed':'')).trim();
const skipFetch=status!=='completed';
const fallback=status==='completed'
  ? ('Commissioning: извлечено '+n+' скважин с датами ввода')
  : (status==='needs_input'?'Commissioning требует уточнения':'Извлечение commissioning не удалось');
const message=String(raw.message||(httpError&&(httpError.message||httpError.description))||fallback);
return [{json:{
  ...raw,
  status:status||'failed',
  message,
  skip_fetch:skipFetch,
  activity_kind:status==='completed'?'agent.progress':(status==='needs_input'?'agent.progress':'agent.failed'),
  status_message:message,
  activity_payload:{
    source:'excel-extractor-agent-workflow',
    operation:'extract_commissioning',
    wells_extracted:n,
    status:status||'failed'
  }
}}];

const RAG_TARGET_BASE="excel_protocol";
const RAG_ACCESS_SCOPE="petroleum-engineering";
const RAG_KNOWLEDGE_TYPES=["protocol_instruction"];
const RAG_TOP_K=8;
const RAG_TOPICS=["протокол", "clarification"];

const opened=$json||{};
const task=$('Normalize excel task').first().json.agent_task||{};
const objective=String(opened.objective||task.objective||'');
const handoff=String(opened.handoff_message||task.handoff_message||'');
const blob=[objective,handoff].join('\n');
const low=blob.toLowerCase();
const topics=RAG_TOPICS.slice();
const task_patterns=[];
if(/дат|ввод|commission/.test(low)) task_patterns.push('даты ввода');
if(/таблиц|query|дебит|истори|управлен/.test(low)) task_patterns.push('извлечь таблицу');
if(/уточн|ambigu|clarif/.test(low)) task_patterns.push('clarification_needed');
const query=blob.trim().replace(/\b[\w.-]+\.(xlsx|xls|xlsm|inc|dev|txt|csv)\b/gi,' ').replace(/\s+/g,' ').trim().slice(0,800)||'excel protocol instruction';
const retrieval_selector={target_base:RAG_TARGET_BASE,knowledge_types:RAG_KNOWLEDGE_TYPES};
const schedule_retrieval_request={
  query,
  filters:{
    target_base:RAG_TARGET_BASE,
    access_scope:RAG_ACCESS_SCOPE,
    knowledge_types:RAG_KNOWLEDGE_TYPES,
    keyword_families:[],
    topics:[...new Set(topics)],
    task_patterns:[...new Set(task_patterns)]
  },
  top_k:RAG_TOP_K
};
const planner_input=JSON.stringify({
  objective,
  handoff_message:handoff,
  inspect:opened.inspect||{},
  file_name:opened.file_name||'',
  suggested_capability:opened.suggested_capability||''
});
return [{json:{...opened,session_id:opened.session_id,agent_input:planner_input,planner_input,schedule_retrieval_request,retrieval_selector}}];

function unwrapRetrieval(raw){
  const obj=v=>v&&typeof v==='object'&&!Array.isArray(v);
  const src=obj(raw)?raw:{};
  if(obj(src.schedule_retrieval_result)) return src.schedule_retrieval_result;
  if(obj(src.body)&&obj(src.body.schedule_retrieval_result)) return src.body.schedule_retrieval_result;
  if(String(src.contract||'')==='schedule_retrieval_result') return src;
  if(src.error||Number(src.statusCode)>=400) return {status:'failed',findings:[{code:'RETRIEVAL_CALL_FAILED'}],results:[]};
  return src;
}
function compactRetrievalCards(result, selector, limit, textLimit){
  const rows=Array.isArray(result.results)?result.results:[];
  const wantedBase=String(selector.target_base||'');
  const wantedTypes=new Set((selector.knowledge_types||[]).map(v=>String(v).toLowerCase()));
  const cap=Number(limit)||6;
  const cut=Number(textLimit)||700;
  const minText=50;
  const relKeep=0.45;
  const scored=[];
  for(const r of rows){
    if(!r||typeof r!=='object') continue;
    const body=r.body&&typeof r.body==='object'?r.body:{};
    const base=String(r.target_base||body.target_base||(result.filters&&result.filters.target_base)||'');
    const kt=String(r.knowledge_type||body.knowledge_type||'').toLowerCase();
    if(wantedBase&&base&&base!==wantedBase) continue;
    if(wantedTypes.size&&kt&&!wantedTypes.has(kt)) continue;
    const text=String(body.text||body.instruction||r.text||'').trim();
    if(text.length<minText) continue;
    const score=r.rrf_score!=null?Number(r.rrf_score):(body.rrf_score!=null?Number(body.rrf_score):null);
    if(Number.isFinite(score)&&score<=0) continue;
    scored.push({
      knowledge_id:String(r.knowledge_id||body.knowledge_id||''),
      title:String(r.title||body.title||'').slice(0,160),
      knowledge_type:kt||null,
      text:text.slice(0,cut),
      _score:Number.isFinite(score)?score:null
    });
  }
  const finite=scored.map(c=>c._score).filter(s=>s!=null);
  const best=finite.length?Math.max.apply(null,finite):0;
  const floor=best>0?best*relKeep:0;
  const kept=scored.filter(c=>c._score==null||floor<=0||c._score>=floor);
  kept.sort((a,b)=>{
    if(a._score==null&&b._score==null) return 0;
    if(a._score==null) return 1;
    if(b._score==null) return -1;
    return b._score-a._score;
  });
  return kept.slice(0,cap).map(c=>({knowledge_id:c.knowledge_id,title:c.title,knowledge_type:c.knowledge_type,text:c.text}));
}
const prev=$("Prepare AI Agent input").first().json||{};
const raw=$json||{};
const result=unwrapRetrieval(raw);
const fallbackSelector={"target_base": "excel_protocol", "knowledge_types": ["protocol_instruction"]};
const fromPrev=prev.retrieval_selector;
const selector=(fromPrev&&fromPrev.target_base)?{target_base:String(fromPrev.target_base),knowledge_types:Array.isArray(fromPrev.knowledge_types)&&fromPrev.knowledge_types.length?fromPrev.knowledge_types:fallbackSelector.knowledge_types}:fallbackSelector;
const failed=result.status==='abstain'||result.status==='failed'||result.status==='needs_input'||Boolean(raw.error);
const cards=failed?[]:compactRetrievalCards(result,selector,8,1200);
const rag={contract:'mas_rag_evidence',contract_version:'1.0',target_base:selector.target_base,knowledge_types:selector.knowledge_types,status:failed?'unavailable':(cards.length?'ready':'empty'),cards,findings:(Array.isArray(result.findings)?result.findings:[]).slice(0,6).map(f=>f&&f.code).filter(Boolean)};
const note=rag.status==='ready'?"Карточки — срез excel_protocol (protocol_instruction), не schedule_mvp и не orchestrator_routing. Это протокол инструментов (opaque id, query_table, clarification). Строки workbook только из Excel-tools. Не спрашивай HITL про базу знаний.":"Срез excel_protocol пуст или недоступен — работай правилами инструментов. Не спрашивай HITL про RAG и не ходи в другие target_base.";
const planner=`${prev.planner_input||prev.agent_input||''}\n\nRetrieved knowledge (target_base=${selector.target_base}):\n${JSON.stringify(rag,null,2)}\n\n${note}\n`;
return [{json:{...prev,rag,planner_input:planner,agent_input:planner}}];

const agent=$json||{};
const opened=$('Open excel session').first().json||{};
const steps=Array.isArray(agent.intermediateSteps)?agent.intermediateSteps:(Array.isArray(agent.intermediate_steps)?agent.intermediate_steps:[]);
const toolName=step=>{
  if(!step||typeof step!=='object') return '';
  const a=step.action&&typeof step.action==='object'?step.action:step;
  return String(a.tool||a.toolName||a.name||step.tool||'');
};
const tools=steps.map(toolName).filter(Boolean);
const unique=[...new Set(tools)];
const counts={};
for(const name of tools) counts[name]=(counts[name]||0)+1;
const repeated=Object.keys(counts).some(name=>counts[name]>3);
const hasExtraction=tools.some(n=>n==='extract_commissioning'||n==='query_table');
const skipFetch=!hasExtraction||repeated;
const message=hasExtraction&&!repeated
  ? ('Excel Extractor вызвал '+String(tools.length)+' tools: '+unique.join(', '))
  : (repeated
    ? 'Агент повторял один и тот же tool без прогресса. Нужно уточнение.'
    : 'Агент не извлёк данных. Уточните, какие данные нужны.');
return [{json:{
  ...(skipFetch?{
    task_id:opened.task_id||'',
    agent_id:'excel_extractor',
    status:'needs_input',
    message,
    data:{tools_used:unique,total_calls:steps.length},
    artifacts:{},
    issues:[{type:repeated?'repeated_tools':'no_extract'}],
    assumptions:[],
    requests:[{question_id:'Q-clarify',question:message,options:['Даты ввода','Дебиты','Управления','Другое']}]
  }:agent),
  skip_fetch:skipFetch,
  has_extraction:hasExtraction,
  activity_kind:'agent.progress',
  status_message:message,
  activity_payload:{source:'excel-extractor-agent-workflow',total_calls:steps.length,tools_used:unique,iterations:steps.length}
}}];

const fetched=$json||{};
const opened=$('Open excel session').first().json||{};
if(fetched.status){
  return [{json:{
    task_id:fetched.task_id||opened.task_id||'',
    agent_id:'excel_extractor',
    status:fetched.status,
    message:fetched.message||'',
    data:fetched.data||{},
    artifacts:fetched.artifacts||{},
    issues:fetched.issues||[],
    assumptions:fetched.assumptions||[],
    requests:fetched.requests||[]
  }}];
}
return [{json:{
  task_id:opened.task_id||'',
  agent_id:'excel_extractor',
  status:'failed',
  message:String(fetched.message||fetched.error||'Excel Extractor не вернул факты'),
  data:{},
  artifacts:{},
  issues:[{type:'excel_agent_no_result'}],
  assumptions:[],
  requests:[]
}}];
